package com.example.claims.infrastructure.claim;

import com.example.claims.domain.claim.Claim;
import com.example.claims.domain.claim.ClaimId;
import com.example.claims.domain.claim.ClaimRepository;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public final class InMemoryClaimRepository implements ClaimRepository {
    private final Map<ClaimId, Claim> claims = new ConcurrentHashMap<>();

    @Override
    public void save(Claim claim) {
        claims.put(claim.id(), claim);
    }
}
