package com.example.claims.api.claim;

import com.example.claims.application.claim.ExchangeRates;
import com.example.claims.application.claim.SubmitClaim;
import com.example.claims.domain.claim.ClaimRepository;
import com.example.claims.infrastructure.claim.InMemoryClaimRepository;
import com.example.claims.infrastructure.claim.RestExchangeRates;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.client.RestClient;

@Configuration
class ClaimsConfiguration {

    @Bean
    ClaimRepository claimRepository() {
        return new InMemoryClaimRepository();
    }

    @Bean
    ExchangeRates exchangeRates(@Value("${exchange-rates.base-url}") String baseUrl) {
        return new RestExchangeRates(RestClient.builder().baseUrl(baseUrl).build());
    }

    @Bean
    SubmitClaim submitClaim(ClaimRepository claimRepository, ExchangeRates exchangeRates) {
        return new SubmitClaim(claimRepository, exchangeRates);
    }
}
