package com.example.claims.api.claim;

import com.example.claims.application.claim.SubmitClaim;
import com.example.claims.domain.claim.ClaimId;
import com.example.claims.domain.claim.EmployeeId;
import java.math.BigDecimal;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.client.RestClientException;

@RestController
class ClaimController {
    private final SubmitClaim submitClaim;

    ClaimController(SubmitClaim submitClaim) {
        this.submitClaim = submitClaim;
    }

    record SubmitClaimRequest(String employeeId, BigDecimal amount, String currency) {}

    record SubmitClaimResponse(UUID id) {}

    @PostMapping("/claims")
    ResponseEntity<SubmitClaimResponse> submit(@RequestBody SubmitClaimRequest request) {
        ClaimId id = new ClaimId(UUID.randomUUID());
        submitClaim.execute(id, new EmployeeId(request.employeeId()), request.amount(), request.currency());
        return ResponseEntity.status(HttpStatus.CREATED).body(new SubmitClaimResponse(id.value()));
    }

    @ExceptionHandler(IllegalArgumentException.class)
    ResponseEntity<Void> badRequest() {
        return ResponseEntity.badRequest().build();
    }

    @ExceptionHandler({RestClientException.class, IllegalStateException.class})
    ResponseEntity<Void> rateUnavailable() {
        return ResponseEntity.status(HttpStatus.BAD_GATEWAY).build();
    }
}
