package com.example.claims.application.claim;

import com.example.claims.domain.claim.Claim;
import com.example.claims.domain.claim.ClaimId;
import com.example.claims.domain.claim.ClaimRepository;
import com.example.claims.domain.claim.EmployeeId;
import java.math.BigDecimal;
import java.math.RoundingMode;

public final class SubmitClaim {
    private final ClaimRepository claims;
    private final ExchangeRates rates;

    public SubmitClaim(ClaimRepository claims, ExchangeRates rates) {
        this.claims = claims;
        this.rates = rates;
    }

    public void execute(ClaimId id, EmployeeId employeeId, BigDecimal amount, String currency) {
        if (amount == null || currency == null || currency.isBlank()) {
            throw new IllegalArgumentException("amount and currency are required");
        }
        BigDecimal amountInEur = amount.multiply(rates.rateToEur(currency)).setScale(2, RoundingMode.HALF_UP);
        claims.save(Claim.submit(id, employeeId, amount, currency.toUpperCase(), amountInEur));
    }
}
E
