package com.example.claims.infrastructure.claim;

import com.example.claims.application.claim.ExchangeRates;
import java.math.BigDecimal;
import org.springframework.web.client.RestClient;

public final class RestExchangeRates implements ExchangeRates {
    private final RestClient client;

    public RestExchangeRates(RestClient client) {
        this.client = client;
    }

    @Override
    public BigDecimal rateToEur(String currency) {
        RateResponse response = client.get()
                .uri("/rates/{currency}", currency.toUpperCase())
                .retrieve()
                .body(RateResponse.class);
        if (response == null || response.rate() == null) {
            throw new IllegalStateException("no exchange rate for " + currency);
        }
        return response.rate();
    }

    record RateResponse(BigDecimal rate) {}
}
E
